def transform_test_v2(grid):
    bg = 8
    rows = len(grid)
    cols = len(grid[0])

    pos2 = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2]
    pos3 = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 3]

    result = [row[:] for row in grid]

    # Step 1: For columns with both 2 and 3, fill between them
    cols_with_2 = {c for r, c in pos2}
    cols_with_3 = {c for r, c in pos3}

    for c in cols_with_2 & cols_with_3:
        rows_with_2 = {r for r, cc in pos2 if cc == c}
        rows_with_3 = {r for r, cc in pos3 if cc == c}

        max_2_row = max(rows_with_2)
        min_3_row = min(rows_with_3)

        # Fill rows from (max_2_row + 1) to (min_3_row - 1)
        for r in range(max_2_row + 1, min_3_row):
            if result[r][c] == bg:
                result[r][c] = 3

    # Step 2: For columns with only 3 (top 3s), fill from row 1 to just before where anchor is
    # For cols 15-18: top 3s at row 0, no 2s or bottom 3s
    # Fill from 1 to 8 (since bottom anchor is at row 9)
    for c in cols_with_3 - cols_with_2:
        rows_with_3 = {r for r, cc in pos3 if cc == c}
        min_3_row = min(rows_with_3)

        # For cols with top 3s, fill from 1 to before bottom anchor row
        # The "bottom anchor row" is min_3_row if it's the lowest 3 in that column
        fill_end = min_3_row - 1  # Don't fill the 3 itself
        for r in range(1, fill_end + 1):
            if result[r][c] == bg:
                result[r][c] = 3

    # Step 3: Make the middle 3s become 4s
    # Middle 3s are: 3s that are in the same column as 2s (middle groups)
    middle_3s_in_overlap = []
    for r, c in pos3:
        if c in cols_with_2:
            # Check if this 3 is below the 2s in that column
            rows_with_2 = {r2 for r2, cc2 in pos2 if cc2 == c}
            if r > max(rows_with_2):
                middle_3s_in_overlap.append((r, c))

    for r, c in middle_3s_in_overlap:
        result[r][c] = 4

    return result

