def transform_test_v3(grid):
    """
    Fixed: for cols with only top 3s (no any anchor 3s at bottom or 2s),
    fill from row 1 to row 8 (just before the bottommost 3s in the grid, which is at row 9)
    """
    bg = 8
    rows = len(grid)
    cols = len(grid[0])

    pos2 = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2]
    pos3 = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 3]

    result = [row[:] for row in grid]

    # Find the global minimum and maximum row with a 3 (bottom anchor row)
    all_3_rows = {r for r, c in pos3}
    bottom_3_row = max(all_3_rows)  # The bottommost 3 (at row 9)

    rows_with_2 = {c for c in [cc for r, cc in pos2]}
    cols_with_2 = set(c for r, c in pos2)
    cols_with_3 = set(c for r, c in pos3)

    # Step 1: For columns with both 2 and 3, fill between them
    for c in cols_with_2 & cols_with_3:
        rows_with_2_in_c = {r for r, cc in pos2 if cc == c}
        rows_with_3_in_c = {r for r, cc in pos3 if cc == c}

        max_2_row = max(rows_with_2_in_c)
        min_3_row = min(rows_with_3_in_c)

        # Fill rows from (max_2_row + 1) to (min_3_row - 1)
        for r in range(max_2_row + 1, min_3_row):
            if result[r][c] == bg:
                result[r][c] = 3

    # Step 2: For columns with 3s but no 2s, classify them
    for c in cols_with_3 - cols_with_2:
        # Cols 8 has 3 at row 9 (bottom-adjacent), cols 15-18 have 3 at row 0 (top-adjacent)
        min_3_row = min(r for r, cc in pos3 if cc == c)
        max_3_row = max(r for r, cc in pos3 if cc == c)

        if min_3_row == max_3_row == 0:
            # Top 3s only, fill from 1 to before bottom_3_row
            fill_end = bottom_3_row - 1
            for r in range(1, fill_end + 1):
                if result[r][c] == bg:
                    result[r][c] = 3
        elif max_3_row == bottom_3_row:
            # Bottom-adjacent 3s (like col 8), fill from 1 to before max_3_row
            fill_end = min_3_row - 1
            for r in range(1, fill_end + 1):
                if result[r][c] == bg:
                    result[r][c] = 3
        else:
            # Mixed: also fill between (like middle 3s that have 2s)
            rows_with_2_in_c = max(rows_with_2_in_c if (c in cols_with_2) else [])
            min_3_row = min(r for r, cc in pos3 if cc == c)
            max_2_row = max(r for r, cc in pos2 if cc == c) if c in cols_with_2 else 0
            for r in range(max_2_row + 1, min_3_row):
                if result[r][c] == bg:
                    result[r][c] = 3

    # Step 3: Make middle 3s become 4s
    # Middle 3s are 3s at bottom that are above 2s in same column
    middle_3s = []
    for r, c in pos3:
        if c in cols_with_2:
            rows_with_2_in_c = {r2 for r2, cc in pos2 if cc == c}
            if r > max(rows_with_2_in_c):
                # This 3 is below the 2s in this column -> make it a 4
                middle_3s.append((r, c))

    for r, c in middle_3s:
        result[r][c] = 4

    return result

